CREATE TABLE platform_memory_records (
  memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  memory_key VARCHAR(160) NOT NULL,
  memory_type VARCHAR(40) NOT NULL CHECK (memory_type IN ('analysis_case','behavior_habit','business_fact','preference','warning','other')),
  subject_type VARCHAR(24) NOT NULL CHECK (subject_type IN ('user','role','org','tenant')),
  subject_id VARCHAR(300) NOT NULL,
  title VARCHAR(500) NOT NULL,
  content JSONB NOT NULL,
  content_hash CHAR(64) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'candidate' CHECK (status IN ('candidate','review','active','superseded','expired','rejected')),
  confidence NUMERIC(7,4) NOT NULL DEFAULT 0 CHECK (confidence BETWEEN 0 AND 1),
  weight NUMERIC(9,6) NOT NULL DEFAULT 1 CHECK (weight >= 0),
  valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  supersedes_memory_id UUID REFERENCES platform_memory_records(memory_id) ON DELETE SET NULL,
  source_trace_id VARCHAR(100),
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
