COMMENT ON COLUMN platform_memory_records.status IS '生命周期。';
COMMENT ON COLUMN platform_memory_records.confidence IS '置信度。';
COMMENT ON COLUMN platform_memory_records.weight IS '随时间衰减的权重。';
COMMENT ON COLUMN platform_memory_records.valid_from IS '生效时间。';
COMMENT ON COLUMN platform_memory_records.expires_at IS '过期时间。';
COMMENT ON COLUMN platform_memory_records.supersedes_memory_id IS '被替代记忆。';
