CREATE TABLE platform_model_calls (
  model_call_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  model_call_key VARCHAR(300) NOT NULL UNIQUE,
  analysis_task_id UUID,
  subject_type VARCHAR(64) NOT NULL DEFAULT 'analysis_task',
  subject_id VARCHAR(300) NOT NULL,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  model_integration_id UUID NOT NULL REFERENCES platform_model_integrations(model_integration_id) ON DELETE RESTRICT,
  provider_model_name VARCHAR(200) NOT NULL DEFAULT '',
  prompt_template_id UUID REFERENCES platform_prompt_templates(prompt_template_id) ON DELETE SET NULL,
  request_hash CHAR(64) NOT NULL,
  response_hash CHAR(64),
  status VARCHAR(24) NOT NULL CHECK (status IN ('queued','running','succeeded','degraded','failed','cancelled')),
  input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
  output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
  usage_source VARCHAR(24) NOT NULL DEFAULT 'estimated' CHECK (usage_source IN ('provider','estimated')),
  cost_amount NUMERIC(18,6) NOT NULL DEFAULT 0 CHECK (cost_amount >= 0),
  latency_ms INTEGER CHECK (latency_ms >= 0),
  error_code VARCHAR(100),
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_model_calls IS '模型调用的输入证据引用、用量、成本和结果状态。';
COMMENT ON COLUMN platform_model_calls.model_call_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_model_calls.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_model_calls.model_call_key IS 'API 与审计使用的稳定模型调用标识。';
COMMENT ON COLUMN platform_model_calls.analysis_task_id IS '关联分析任务。';
COMMENT ON COLUMN platform_model_calls.subject_type IS '调用所属业务对象类型。';
COMMENT ON COLUMN platform_model_calls.subject_id IS '调用所属分析、修复、报告或任务对象稳定 ID。';
COMMENT ON COLUMN platform_model_calls.revision IS '同一业务对象内的调用序号。';
COMMENT ON COLUMN platform_model_calls.model_integration_id IS '实际模型。';
COMMENT ON COLUMN platform_model_calls.provider_model_name IS '本次调用实际命中的提供商模型名快照。';
COMMENT ON COLUMN platform_model_calls.prompt_template_id IS 'Prompt 版本。';
COMMENT ON COLUMN platform_model_calls.request_hash IS '脱敏请求 hash。';
COMMENT ON COLUMN platform_model_calls.response_hash IS '响应 hash。';
COMMENT ON COLUMN platform_model_calls.status IS '调用状态。';
COMMENT ON COLUMN platform_model_calls.input_tokens IS '输入 token。';
COMMENT ON COLUMN platform_model_calls.output_tokens IS '输出 token。';
COMMENT ON COLUMN platform_model_calls.usage_source IS 'Token 用量来自提供商还是估算。';
COMMENT ON COLUMN platform_model_calls.cost_amount IS '成本。';
COMMENT ON COLUMN platform_model_calls.latency_ms IS '耗时。';
COMMENT ON COLUMN platform_model_calls.error_code IS '稳定错误码。';
COMMENT ON COLUMN platform_model_calls.created_by IS '创建人。';
COMMENT ON COLUMN platform_model_calls.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_model_calls.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_model_calls.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_model_calls_tenant_updated ON platform_model_calls (tenant_id, updated_at, model_call_id);
CREATE INDEX idx_platform_model_calls_task ON platform_model_calls (tenant_id, analysis_task_id, created_at);
CREATE UNIQUE INDEX uq_platform_model_calls_subject ON platform_model_calls (tenant_id, subject_type, subject_id, revision);

CREATE TABLE platform_connection_versions (
  connection_version_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
