COMMENT ON COLUMN platform_connection_versions.credential_ciphertext IS 'KMS envelope 密文。';
COMMENT ON COLUMN platform_connection_versions.key_version IS 'KMS key version。';
COMMENT ON COLUMN platform_connection_versions.config_hash IS '规范化配置 hash。';
COMMENT ON COLUMN platform_connection_versions.validation_status IS '验证状态。';
COMMENT ON COLUMN platform_connection_versions.validation_result IS '脱敏测试结果。';
COMMENT ON COLUMN platform_connection_versions.verified_at IS '验证成功时间。';
COMMENT ON COLUMN platform_connection_versions.published_at IS '发布生效时间。';
COMMENT ON COLUMN platform_connection_versions.created_by IS '创建人。';
COMMENT ON COLUMN platform_connection_versions.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_connection_versions.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_connection_versions.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_connection_versions_tenant_updated ON platform_connection_versions (tenant_id, updated_at, connection_version_id);
CREATE UNIQUE INDEX uq_platform_connection_versions ON platform_connection_versions (connection_id, version_no);

CREATE TABLE platform_datasets (
  dataset_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  connection_id UUID NOT NULL REFERENCES platform_data_connections(connection_id) ON DELETE RESTRICT,
  dataset_code VARCHAR(200) NOT NULL,
  dataset_name VARCHAR(300) NOT NULL,
  physical_locator JSONB NOT NULL,
  dataset_type VARCHAR(32) NOT NULL CHECK (dataset_type IN ('table','view','api','file_collection','stream','semantic')),
  data_classification VARCHAR(24) NOT NULL DEFAULT 'internal' CHECK (data_classification IN ('public','internal','confidential','restricted')),
  freshness_sla_seconds INTEGER CHECK (freshness_sla_seconds > 0),
  status VARCHAR(24) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','degraded','deprecated','disabled')),
  schema_hash CHAR(64),
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_datasets IS '真实数据集、库表、API 资源或文件集合的元数据。';
COMMENT ON COLUMN platform_datasets.dataset_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_datasets.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_datasets.connection_id IS '数据连接。';
COMMENT ON COLUMN platform_datasets.dataset_code IS '租户内稳定编码。';
COMMENT ON COLUMN platform_datasets.dataset_name IS '名称。';
COMMENT ON COLUMN platform_datasets.physical_locator IS 'schema/table、API path 或对象前缀。';
COMMENT ON COLUMN platform_datasets.dataset_type IS '类型。';
COMMENT ON COLUMN platform_datasets.data_classification IS '敏感级别。';
COMMENT ON COLUMN platform_datasets.freshness_sla_seconds IS '新鲜度 SLA。';
COMMENT ON COLUMN platform_datasets.status IS '生命周期。';
COMMENT ON COLUMN platform_datasets.schema_hash IS '字段 schema hash。';
COMMENT ON COLUMN platform_datasets.created_by IS '创建人。';
COMMENT ON COLUMN platform_datasets.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_datasets.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_datasets.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_datasets_tenant_updated ON platform_datasets (tenant_id, updated_at, dataset_id);
CREATE UNIQUE INDEX uq_platform_datasets_code ON platform_datasets (tenant_id, dataset_code);
CREATE INDEX idx_platform_datasets_connection ON platform_datasets (connection_id, status);

