CREATE TABLE platform_file_attachments (
  attachment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  attachment_key VARCHAR(160) NOT NULL,
  artifact_id UUID NOT NULL REFERENCES platform_data_artifacts(artifact_id) ON DELETE RESTRICT,
  owner_user_id UUID NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  resource_type VARCHAR(80) NOT NULL,
  resource_id VARCHAR(300) NOT NULL,
  file_name VARCHAR(500) NOT NULL,
