  scan_status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (scan_status IN ('pending','clean','infected','failed')),
  processing_status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (processing_status IN ('pending','processing','ready','failed')),
  processing_error VARCHAR(200) NOT NULL DEFAULT '',
