CREATE TABLE platform_analysis_steps (
  analysis_step_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  analysis_task_id UUID NOT NULL REFERENCES platform_analysis_tasks(analysis_task_id) ON DELETE CASCADE,
  step_code VARCHAR(120) NOT NULL,
  sequence_no INTEGER NOT NULL CHECK (sequence_no >= 0),
