CREATE TABLE platform_automation_task_runs (
  automation_run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  automation_run_key VARCHAR(160) NOT NULL,
  automation_task_id UUID NOT NULL REFERENCES platform_automation_tasks(automation_task_id) ON DELETE RESTRICT,
  idempotency_key VARCHAR(200) NOT NULL,
  trigger_type VARCHAR(24) NOT NULL,
  trigger_payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  status VARCHAR(24) NOT NULL CHECK (status IN ('queued','running','retry_wait','succeeded','failed','cancelled')),
  attempt_no INTEGER NOT NULL DEFAULT 1 CHECK (attempt_no > 0),
  lease_owner VARCHAR(200),
  lease_expires_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ,
  finished_at TIMESTAMPTZ,
  next_retry_at TIMESTAMPTZ,
  result_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  error_code VARCHAR(100),
  error_summary TEXT,
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_automation_task_runs IS '自动化任务每次运行、租约、重试和恢复状态。';
COMMENT ON COLUMN platform_automation_task_runs.automation_run_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_automation_task_runs.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_automation_task_runs.automation_run_key IS 'API 使用的稳定运行标识。';
COMMENT ON COLUMN platform_automation_task_runs.automation_task_id IS '任务定义。';
COMMENT ON COLUMN platform_automation_task_runs.idempotency_key IS '幂等键。';
COMMENT ON COLUMN platform_automation_task_runs.trigger_type IS '实际触发类型。';
COMMENT ON COLUMN platform_automation_task_runs.trigger_payload IS '脱敏触发参数。';
COMMENT ON COLUMN platform_automation_task_runs.status IS '状态。';
COMMENT ON COLUMN platform_automation_task_runs.attempt_no IS '尝试次数。';
COMMENT ON COLUMN platform_automation_task_runs.lease_owner IS 'Worker 租约。';
COMMENT ON COLUMN platform_automation_task_runs.lease_expires_at IS '租约到期。';
COMMENT ON COLUMN platform_automation_task_runs.started_at IS '开始时间。';
COMMENT ON COLUMN platform_automation_task_runs.finished_at IS '结束时间。';
COMMENT ON COLUMN platform_automation_task_runs.next_retry_at IS '下次重试。';
COMMENT ON COLUMN platform_automation_task_runs.result_refs IS '产物和业务结果 ID。';
COMMENT ON COLUMN platform_automation_task_runs.error_code IS '稳定错误码。';
COMMENT ON COLUMN platform_automation_task_runs.error_summary IS '脱敏错误摘要。';
COMMENT ON COLUMN platform_automation_task_runs.created_by IS '创建人。';
COMMENT ON COLUMN platform_automation_task_runs.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_automation_task_runs.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_automation_task_runs.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_automation_task_runs_tenant_updated ON platform_automation_task_runs (tenant_id, updated_at, automation_run_id);
CREATE UNIQUE INDEX uq_platform_automation_runs_key ON platform_automation_task_runs (tenant_id, automation_run_key);
CREATE UNIQUE INDEX uq_platform_automation_runs_idempotency ON platform_automation_task_runs (tenant_id, automation_task_id, idempotency_key);
CREATE INDEX idx_platform_automation_runs_status ON platform_automation_task_runs (tenant_id, status, created_at);

CREATE TABLE platform_todos (
  todo_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  todo_key VARCHAR(160) NOT NULL,
  title VARCHAR(500) NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  owner_user_id UUID NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  assignee_user_id UUID NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  org_unit_id UUID REFERENCES platform_org_units(org_unit_id) ON DELETE SET NULL,
  source_type VARCHAR(40),
  source_id UUID,
  priority VARCHAR(16) NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  status VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','blocked','completed','cancelled')),
  due_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  result_summary JSONB NOT NULL DEFAULT '{}'::jsonb,
  todo_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_todos IS '可分配、提醒、关联证据和回收结果的待办任务。';
COMMENT ON COLUMN platform_todos.todo_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_todos.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_todos.todo_key IS 'API 使用的稳定待办标识。';
COMMENT ON COLUMN platform_todos.title IS '标题。';
COMMENT ON COLUMN platform_todos.description IS '说明。';
COMMENT ON COLUMN platform_todos.owner_user_id IS '创建人。';
COMMENT ON COLUMN platform_todos.assignee_user_id IS '责任人。';
COMMENT ON COLUMN platform_todos.org_unit_id IS '责任机构。';
COMMENT ON COLUMN platform_todos.source_type IS '周报、分析、告警等来源。';
COMMENT ON COLUMN platform_todos.source_id IS '来源 ID。';
COMMENT ON COLUMN platform_todos.priority IS '优先级。';
COMMENT ON COLUMN platform_todos.status IS '状态。';
COMMENT ON COLUMN platform_todos.due_at IS '截止时间。';
COMMENT ON COLUMN platform_todos.completed_at IS '完成时间。';
COMMENT ON COLUMN platform_todos.result_summary IS '执行结果和指标效果。';
COMMENT ON COLUMN platform_todos.todo_metadata IS '页面所需清单、标签和来源展示元数据。';
COMMENT ON COLUMN platform_todos.created_by IS '创建人。';
COMMENT ON COLUMN platform_todos.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_todos.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_todos.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_todos_tenant_updated ON platform_todos (tenant_id, updated_at, todo_id);
CREATE UNIQUE INDEX uq_platform_todos_key ON platform_todos (tenant_id, todo_key);
CREATE INDEX idx_platform_todos_assignee ON platform_todos (tenant_id, assignee_user_id, status, due_at);
CREATE INDEX idx_platform_todos_source ON platform_todos (tenant_id, source_type, source_id);

CREATE TABLE platform_alert_events (
  alert_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  alert_rule_id UUID NOT NULL REFERENCES platform_alert_rules(alert_rule_id) ON DELETE RESTRICT,
  dedupe_key VARCHAR(300) NOT NULL,
  severity VARCHAR(16) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved','suppressed')),
  resource_type VARCHAR(40) NOT NULL,
  resource_id UUID,
  summary TEXT NOT NULL,
  evidence JSONB NOT NULL,
  first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  occurrence_count INTEGER NOT NULL DEFAULT 1 CHECK (occurrence_count > 0),
  acknowledged_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  resolved_at TIMESTAMPTZ,
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_alert_events IS '告警规则命中、去重、确认、解决和证据。';
COMMENT ON COLUMN platform_alert_events.alert_event_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_alert_events.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_alert_events.alert_rule_id IS '告警规则。';
COMMENT ON COLUMN platform_alert_events.dedupe_key IS '冷却窗口内去重键。';
COMMENT ON COLUMN platform_alert_events.severity IS '严重度。';
COMMENT ON COLUMN platform_alert_events.status IS '处置状态。';
COMMENT ON COLUMN platform_alert_events.resource_type IS '问题资源类型。';
COMMENT ON COLUMN platform_alert_events.resource_id IS '问题资源 ID。';
COMMENT ON COLUMN platform_alert_events.summary IS '摘要。';
COMMENT ON COLUMN platform_alert_events.evidence IS '触发值和证据引用。';
COMMENT ON COLUMN platform_alert_events.first_seen_at IS '首次发现。';
COMMENT ON COLUMN platform_alert_events.last_seen_at IS '最近发现。';
COMMENT ON COLUMN platform_alert_events.occurrence_count IS '发生次数。';
COMMENT ON COLUMN platform_alert_events.acknowledged_by IS '确认人。';
COMMENT ON COLUMN platform_alert_events.resolved_at IS '解决时间。';
COMMENT ON COLUMN platform_alert_events.created_by IS '创建人。';
COMMENT ON COLUMN platform_alert_events.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_alert_events.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_alert_events.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_alert_events_tenant_updated ON platform_alert_events (tenant_id, updated_at, alert_event_id);
CREATE INDEX idx_platform_alert_events_open ON platform_alert_events (tenant_id, status, severity, last_seen_at);
CREATE INDEX idx_platform_alert_events_dedupe ON platform_alert_events (tenant_id, alert_rule_id, dedupe_key, last_seen_at);

CREATE TABLE platform_notification_deliveries (
  delivery_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  delivery_key VARCHAR(160) NOT NULL,
  subscription_id UUID REFERENCES platform_subscriptions(subscription_id) ON DELETE SET NULL,
  outbox_event_id UUID NOT NULL REFERENCES platform_outbox_events(outbox_event_id) ON DELETE RESTRICT,
  recipient_user_id UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  channel VARCHAR(24) NOT NULL CHECK (channel IN ('in_app','email','feishu','wecom','sms','webhook')),
  template_code VARCHAR(160) NOT NULL,
  payload_ref JSONB NOT NULL,
  idempotency_key VARCHAR(200) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sending','accepted','delivered','failed','bounced','cancelled','suppressed','dead_letter')),
  provider_message_id VARCHAR(300),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  next_attempt_at TIMESTAMPTZ,
  accepted_at TIMESTAMPTZ,
  delivered_at TIMESTAMPTZ,
  error_code VARCHAR(100),
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_notification_deliveries IS '每条通知的真实渠道投递、回执和重试。';
COMMENT ON COLUMN platform_notification_deliveries.delivery_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_notification_deliveries.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_notification_deliveries.delivery_key IS 'API 使用的稳定投递标识。';
COMMENT ON COLUMN platform_notification_deliveries.subscription_id IS '订阅。';
COMMENT ON COLUMN platform_notification_deliveries.outbox_event_id IS '来源领域事件。';
COMMENT ON COLUMN platform_notification_deliveries.recipient_user_id IS '接收用户。';
COMMENT ON COLUMN platform_notification_deliveries.channel IS '渠道。';
COMMENT ON COLUMN platform_notification_deliveries.template_code IS '通知模板。';
COMMENT ON COLUMN platform_notification_deliveries.payload_ref IS '内容或对象引用，不复制敏感正文。';
COMMENT ON COLUMN platform_notification_deliveries.idempotency_key IS '投递幂等键。';
COMMENT ON COLUMN platform_notification_deliveries.status IS '真实状态。';
COMMENT ON COLUMN platform_notification_deliveries.provider_message_id IS '渠道消息 ID。';
COMMENT ON COLUMN platform_notification_deliveries.attempt_count IS '尝试次数。';
COMMENT ON COLUMN platform_notification_deliveries.next_attempt_at IS '下次尝试。';
COMMENT ON COLUMN platform_notification_deliveries.accepted_at IS '渠道受理时间。';
COMMENT ON COLUMN platform_notification_deliveries.delivered_at IS '送达时间。';
COMMENT ON COLUMN platform_notification_deliveries.error_code IS '错误码。';
COMMENT ON COLUMN platform_notification_deliveries.created_by IS '创建人。';
COMMENT ON COLUMN platform_notification_deliveries.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_notification_deliveries.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_notification_deliveries.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_notification_deliveries_tenant_updated ON platform_notification_deliveries (tenant_id, updated_at, delivery_id);
CREATE UNIQUE INDEX uq_platform_notification_delivery_key ON platform_notification_deliveries (tenant_id, delivery_key);
CREATE UNIQUE INDEX uq_platform_notification_deliveries ON platform_notification_deliveries (tenant_id, channel, idempotency_key);
CREATE INDEX idx_platform_notification_deliveries_status ON platform_notification_deliveries (tenant_id, status, next_attempt_at);

CREATE TABLE platform_bridge_enrollments (
  enrollment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  enrollment_key VARCHAR(160) NOT NULL UNIQUE,
  device_code_hash CHAR(64) NOT NULL UNIQUE,
  user_code_hash CHAR(64) NOT NULL UNIQUE,
  channel VARCHAR(32) NOT NULL CHECK (channel IN ('workbuddy','codex','qwork')),
  device_name VARCHAR(160) NOT NULL,
  verifier_hash CHAR(64) NOT NULL,
  status VARCHAR(16) NOT NULL CHECK (status IN ('pending','approved','consumed')),
  tenant_id UUID REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  user_id UUID REFERENCES platform_user_profiles(user_id) ON DELETE CASCADE,
  approved_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  expires_at_epoch BIGINT NOT NULL,
  approved_at_epoch BIGINT,
  consumed_at_epoch BIGINT,
  binding_id UUID REFERENCES platform_bridge_bindings(binding_id) ON DELETE SET NULL,
  created_at_epoch BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_bridge_enrollments IS '十分钟内有效、只能领取一次的 Bridge 设备授权事务。';
COMMENT ON COLUMN platform_bridge_enrollments.enrollment_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_bridge_enrollments.enrollment_key IS '不含密钥的稳定授权事务标识。';
COMMENT ON COLUMN platform_bridge_enrollments.device_code_hash IS '设备码 SHA-256；明文不落库。';
COMMENT ON COLUMN platform_bridge_enrollments.user_code_hash IS '用户确认码 SHA-256；明文不落库。';
COMMENT ON COLUMN platform_bridge_enrollments.channel IS '发起授权的客户端渠道。';
COMMENT ON COLUMN platform_bridge_enrollments.device_name IS '客户端提供的设备名称。';
COMMENT ON COLUMN platform_bridge_enrollments.verifier_hash IS '客户端 verifier 的 SHA-256，用于防止设备码被截获后领取。';
COMMENT ON COLUMN platform_bridge_enrollments.status IS '一次性授权事务状态。';
COMMENT ON COLUMN platform_bridge_enrollments.tenant_id IS '批准时绑定的明确租户。';
COMMENT ON COLUMN platform_bridge_enrollments.user_id IS '批准时绑定的用户。';
COMMENT ON COLUMN platform_bridge_enrollments.approved_by IS '在浏览器中点击允许的用户。';
COMMENT ON COLUMN platform_bridge_enrollments.expires_at_epoch IS '授权事务过期的 Unix 秒值。';
COMMENT ON COLUMN platform_bridge_enrollments.approved_at_epoch IS '批准时间。';
COMMENT ON COLUMN platform_bridge_enrollments.consumed_at_epoch IS '令牌被客户端领取的时间；非空后禁止重放。';
COMMENT ON COLUMN platform_bridge_enrollments.binding_id IS '领取后创建的设备绑定。';
COMMENT ON COLUMN platform_bridge_enrollments.created_at_epoch IS '创建时间的 Unix 秒值。';
COMMENT ON COLUMN platform_bridge_enrollments.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_bridge_enrollments.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_bridge_enrollments.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_bridge_enrollments_expiry ON platform_bridge_enrollments (status, expires_at_epoch);

CREATE TABLE platform_analysis_threads (
  thread_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
