  checksum CHAR(64) NOT NULL,
  parent_version_id UUID REFERENCES platform_metric_versions(metric_version_id) ON DELETE RESTRICT,
  submitted_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
