COMMENT ON COLUMN platform_data_quality_results.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_data_quality_results.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_data_quality_results_tenant_updated ON platform_data_quality_results (tenant_id, updated_at, quality_result_id);
CREATE UNIQUE INDEX uq_platform_quality_result_key ON platform_data_quality_results (tenant_id, quality_result_key);
CREATE INDEX idx_platform_data_quality_results_partition ON platform_data_quality_results (tenant_id, partition_id, status);
CREATE INDEX idx_platform_data_quality_results_run ON platform_data_quality_results (tenant_id, acquisition_run_id, evaluated_at);

CREATE TABLE platform_report_comment_replies (
  reply_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  reply_key VARCHAR(160) NOT NULL,
  client_request_id VARCHAR(200),
  comment_id UUID NOT NULL REFERENCES platform_report_comments(comment_id) ON DELETE CASCADE,
  author_user_id UUID NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  reply_body TEXT NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','deleted')),
  created_by UUID REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
);
COMMENT ON TABLE platform_report_comment_replies IS '评论线程中的单条回复。';
COMMENT ON COLUMN platform_report_comment_replies.reply_id IS '服务端生成的稳定主键。';
COMMENT ON COLUMN platform_report_comment_replies.tenant_id IS '所属租户。';
COMMENT ON COLUMN platform_report_comment_replies.reply_key IS 'API 使用的稳定回复标识。';
COMMENT ON COLUMN platform_report_comment_replies.client_request_id IS '客户端请求幂等键。';
COMMENT ON COLUMN platform_report_comment_replies.comment_id IS '主评论。';
COMMENT ON COLUMN platform_report_comment_replies.author_user_id IS '真实作者。';
COMMENT ON COLUMN platform_report_comment_replies.reply_body IS '回复正文。';
COMMENT ON COLUMN platform_report_comment_replies.status IS '状态。';
COMMENT ON COLUMN platform_report_comment_replies.created_by IS '创建人。';
COMMENT ON COLUMN platform_report_comment_replies.created_at IS '创建时间，统一 UTC。';
COMMENT ON COLUMN platform_report_comment_replies.updated_at IS '最后更新时间，统一 UTC。';
COMMENT ON COLUMN platform_report_comment_replies.lock_version IS '乐观锁版本。';
CREATE INDEX idx_platform_report_comment_replies_tenant_updated ON platform_report_comment_replies (tenant_id, updated_at, reply_id);
CREATE UNIQUE INDEX uq_platform_report_reply_key ON platform_report_comment_replies (tenant_id, reply_key);
CREATE UNIQUE INDEX uq_platform_report_reply_request ON platform_report_comment_replies (tenant_id, comment_id, client_request_id) WHERE client_request_id IS NOT NULL;
CREATE INDEX idx_platform_report_comment_replies ON platform_report_comment_replies (comment_id, created_at);

